import Foundation
import Darwin

enum ReadBoundedError: Error, Equatable {
    case io(errno: Int32)
    case oversize
}

/// Reads from `fd` until EOF, retaining at most `cap` bytes.
/// If more than `cap` bytes exist, throws `.oversize` after reading one sentinel byte.
func readBounded(fd: Int32, cap: Int) throws -> Data {
    precondition(cap >= 0 && cap < Int.max, "cap out of range")
    let limit = cap + 1                                  // cap + one-byte overflow sentinel
    var out = Data(capacity: min(limit, 16384))
    var buf = [UInt8](repeating: 0, count: 16384)        // fixed 16 KiB scratch buffer
    var eintrBudget = 8                                  // total EINTR retries allowed
    while out.count < limit {
        let want = min(buf.count, limit - out.count)     // never fetch past the sentinel
        let n = buf.withUnsafeMutableBytes { raw -> Int in
            Darwin.read(fd, raw.baseAddress, want)
        }
        if n > 0 {                                       // partial read: accumulate, keep going
            out.append(contentsOf: buf[0..<n])
            continue
        }
        if n == 0 { return out }                         // actual EOF within bound
        let err = errno                                  // n < 0: inspect errno immediately
        if err == EINTR, eintrBudget > 0 { eintrBudget -= 1; continue }
        throw ReadBoundedError.io(errno: err)
    }
    throw ReadBoundedError.oversize                      // sentinel byte arrived: input > cap
}
```

Notes for the root integrator:
- Retained input never exceeds `cap + 1` bytes; `want` shrinks so the final `read` cannot overshoot the sentinel.
- `.oversize` is thrown as soon as byte `cap + 1` is observed; the fd is left positioned after that byte (caller decides whether to drain/close).
- EINTR budget is total (8), not per-call; a 9th EINTR surfaces as `.io(errno: EINTR)`.
- EAGAIN/EWOULDBLOCK on a non-blocking fd is treated as a hard `.io` error by design; no polling or timeout is attempted.
